mapper.select:
select count(id) from user


        and create_time < #{dayMax}


        and create_time > #{dayMin}

select count(id) from Orders


        and order_time < #{dayMax}


        and order_time > #{dayMin}


        and status = #{status}

select od.name, sum(od.number) from order_detail od left join orders o on od.order_id= o.id where o.status = 5
and o.order_time < #{Max}
and o.order_time > #{Min}
group by od.name order by sum(od.number) desc limit 0,10
